/// </summary>
[ExtensionOf(formDataFieldStr(InventSite, InventSite, AVAAgentSite))]
final class AVAInventSiteFrm_InventSiteDS_AVAAgentSiteFld_Extension
{
}

Method.Source:
/// <summary>
///     AVA <c>modified</c> method.
///     AVA - Schneider 18.03.2024
/// </summary>
public void modified()
{
    FormCheckBoxControl locFormCheckBoxControl;
    FormStringControl   locFormStringControl;
    FormDataSource      locFormDataSource;
    InventSite          locInventSite;

    next modified();

    locFormCheckBoxControl  = element.InventSite_AVAAgentSite;
    locFormStringControl    = element.InventSite_AVAEmailAgent;

    if(locFormCheckBoxControl.checked())
    {
        locFormStringControl.enabled(true);
    }
    else
    {
        locFormDataSource           = element.InventSite_DS;
        locInventSite               = locFormDataSource.cursor();
        locInventSite.AVAEmailAgent = '';
        locFormStringControl.enabled(false);
    }
}
